class OrdersViewModel(private val activity: MainActivity) : ViewModel() {
    val orders = MutableLiveData<List<Order>>()

    fun load(userId: String) {
        GlobalScope.launch(Dispatchers.Main) {
            val res = api.getOrders(userId).execute()   // Retrofit Call<List<Order>>, blocking
            orders.value = res.body()!!
            Toast.makeText(activity, "Orders loaded", Toast.LENGTH_SHORT).show()
        }
    }
}

class OrdersFragment : Fragment(R.layout.fragment_orders) {
    private val adapter = OrdersAdapter()

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        val userId = requireArguments().getString("userId")!!
        val vm = OrdersViewModel(requireActivity() as MainActivity)
        vm.load(userId)
        vm.orders.observe(this) { list -> adapter.submitList(list) }
    }
}

// Reported problems: crashes on some phones when the network is slow or off,
// the list reloads (and the toast shows) every time the phone is rotated,
// and memory tools flag a leaked MainActivity.
